from datetime import datetime

class EmailClient:
    def __init__(self, addr, capacity) -> None:
        self._addr = addr
        self._capacity = capacity
        self._inbox = []

    @property
    def addr(self):
        return self._addr

    @addr.setter
    def addr(self, value):
        self._addr = value

    @property
    def capacity(self):
        return self._capacity

    @capacity.setter
    def capacity(self, value):
        self._capacity = value

    @property
    def inbox(self):
        return self._inbox

    @inbox.setter
    def inbox(self, value):
        self._inbox = value

    def send_to(self, recv, content, size):
        if not recv.is_full_with_one_more_email(size):
            self._add_email_to_inbox(recv, content, size)
            return True
        else:
            self.clear_inbox(size)
            return False

    def _add_email_to_inbox(self, recv, content, size):
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        email = {
            "sender": self.addr,
            "receiver": recv.addr,
            "content": content,
            "size": size,
            "time": timestamp,
            "state": "unread"
        }
        recv.inbox.append(email)

    def fetch(self):
        email = self._find_first_unread_email()
        if email is not None:
            email['state'] = "read"
        return email

    def _find_first_unread_email(self):
        for email in self.inbox:
            if email['state'] == "unread":
                return email
        return None

    def is_full_with_one_more_email(self, size):
        return self.get_occupied_size() + size > self.capacity

    def get_occupied_size(self):
        return sum(email["size"] for email in self.inbox)

    def clear_inbox(self, size):
        if not self.addr:
            return
        freed_space = 0
        while freed_space < size and self.inbox:
            email = self.inbox[0]
            freed_space += email['size']
            del self.inbox[0]
